 34→export const loader = async ({ request }: LoaderFunctionArgs) => {
 35→  const { session, admin } = await authenticate.admin(request);
 36→  const shop = session.shop;
 37→
 38→  let config = await db.widgetConfig.findUnique({ where: { shop } });
 39→
 40→  if (!config) {
 41→    config = await db.widgetConfig.create({ data: { shop } });
 42→  }
 43→
 44→  const subscription = await getShopSubscription(shop);
 45→
 46→  return { config, subscription };
 47→};
